from common import *
import io
m=load(); s=scp(); out=io.StringIO()
def P(*a): print(*a,file=out)
def sc(ds,col='rate_per_100k',name=None):
    d=county_scp(ds,s)[['fips',col]].rename(columns={col:name or ds}); return d
for ds,col,nm in [('breast_late_all','pct_late','breast_pct_late'),('crc_late_all','pct_late','crc_pct_late'),('breast_inc_all','rate_per_100k','breast_inc'),('crc_inc_all','rate_per_100k','crc_inc'),('breast_mort_all','rate_per_100k','breast_mort'),('crc_mort_all','rate_per_100k','crc_mort')]:
    m=m.merge(sc(ds,col,nm),on='fips',how='left')
ac=county_scp('breast_late_all')[['fips','avg_annual_count']].rename(columns={'avg_annual_count':'breast_late_n'}); m=m.merge(ac,on='fips',how='left')
ac=county_scp('crc_late_all')[['fips','avg_annual_count']].rename(columns={'avg_annual_count':'crc_late_n'}); m=m.merge(ac,on='fips',how='left')
m['pcp10k']=m.ahrf_pcp_total23/m.ahrf_pop23*1e4; m['pov10']=m.child_poverty/10; m['black10']=m.pct_black_nh/10
P("# Paper 05 — public-data supplement (AHRF PCP/HPSA; PLACES 2020 sensitivity; adjusted late-stage models)\n")
P("Generated by `p05b.py` 2026-11-27. Screening: CDC PLACES 2025 release (BRFSS 2022; CRC ages 45-75, mammography 50-74), PLACES 2023 release (BRFSS 2020; CRC ages 50-75, mammography 50-74) as sensitivity, CHR Medicare FFS mammography (2023). Stage: SCP late-stage % 2019-2023 (county published for CRC n=75; breast n=69). PCP: HRSA AHRF 2023 MD+DO per 10k. PLACES is model-based (MRP) so screening-vs-poverty/demographic associations are partly circular.\n")
P("## A. PLACES 2022 vs 2020 screening estimates (consistency)\n")
rows=[]
for a,b,l in [('pl_colon_screen','pl20_colon','CRC screening'),('pl_mammouse','pl20_mammo','Mammography')]:
    n,r,p=spearman(m[a],m[b]); rows.append([l,m[a].median(),m[b].median(),n,r,p])
P(pd.DataFrame(rows,columns=['Measure','Median 2025 release (BRFSS 2022)','Median 2023 release (BRFSS 2020)','n','Spearman rho between releases','p']).to_markdown(index=False,floatfmt='.3g')); P()
P("Note: CRC screening age range differs between releases (45-75 vs 50-75), so levels are not comparable.\n")
P("## B. Spearman: screening and PCP supply vs late-stage share (counties with published % late stage)\n")
rows=[]
for x,l in [('pl_colon_screen','CRC screening, PLACES 2022'),('pl20_colon','CRC screening, PLACES 2020'),('pcp10k','PCP per 10k (AHRF)'),('ahrf_hpsa_prim25','Primary-care HPSA code'),('child_poverty','Child poverty %'),('pct_black_nh','% Black NH'),('nonmetro','Nonmetro')]:
    n,r,p=spearman(m[x],m.crc_pct_late); rows.append(['CRC % late',l,n,r,p])
for x,l in [('mammography_pct','Mammography, CHR Medicare 2023'),('pl_mammouse','Mammography, PLACES 2022'),('pl20_mammo','Mammography, PLACES 2020'),('pcp10k','PCP per 10k (AHRF)'),('ahrf_hpsa_prim25','Primary-care HPSA code'),('child_poverty','Child poverty %'),('pct_black_nh','% Black NH'),('nonmetro','Nonmetro')]:
    n,r,p=spearman(m[x],m.breast_pct_late); rows.append(['Breast % late',l,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','Predictor','n','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
P("## C. Adjusted models: breast % late stage ~ Medicare mammography + context (OLS HC3, WLS by late-stage avg annual count)\n")
xs=['mammography_pct','pcp10k','pov10','nonmetro']
mod,t,n=ols(m,'breast_pct_late',xs); P(f"OLS n={n}, R2={mod.rsquared:.2f}\n"); P(t.round(3).to_markdown()); P()
d=m[['breast_pct_late']+xs+['breast_late_n']].dropna(); w=sm.WLS(d.breast_pct_late,sm.add_constant(d[xs]),weights=d.breast_late_n).fit(cov_type='HC3')
P("WLS\n"); P(pd.DataFrame({'coef':w.params,'ci_lo':w.conf_int()[0],'ci_hi':w.conf_int()[1],'p':w.pvalues}).round(3).to_markdown()); P()
P("## D. Adjusted models: CRC % late stage ~ CRC screening (PLACES 2022) + context\n")
xs=['pl_colon_screen','pcp10k','pov10','nonmetro']
mod,t,n=ols(m,'crc_pct_late',xs); P(f"OLS n={n}, R2={mod.rsquared:.2f}\n"); P(t.round(3).to_markdown()); P()
xs=['pl20_colon','pcp10k','pov10','nonmetro']
mod,t,n=ols(m,'crc_pct_late',xs); P(f"Sensitivity with PLACES 2020 screening: OLS n={n}, R2={mod.rsquared:.2f}\n"); P(t.round(3).to_markdown()); P()
P("## E. Mammography (CHR Medicare) vs PCP supply (AHRF) and HPSA\n")
xs=['pcp10k','pov10','nonmetro','dra_county']
mod,t,n=ols(m,'mammography_pct',xs); P(f"OLS n={n}, R2={mod.rsquared:.2f}; coefficients in percentage points of Medicare women 65-74 screened\n"); P(t.round(3).to_markdown()); P()
g=m.groupby('ahrf_hpsa_prim25')[['mammography_pct','pl_colon_screen']].median().round(1); P("Medians by primary-care HPSA code\n"); P(g.to_markdown()); P()
P("## F. Statewide screening context (state rows from SCP; PLACES county medians)\n")
P(f"County medians: CRC screening (PLACES 2022, ages 45-75) {m.pl_colon_screen.median():.1f}%; mammography (PLACES 2022) {m.pl_mammouse.median():.1f}%; CHR Medicare mammography {m.mammography_pct.median():.0f}%.\n")
m[['fips','county','population','nonmetro','dra_county','pcp10k','ahrf_hpsa_prim25','pl_colon_screen','pl20_colon','pl_mammouse','pl20_mammo','mammography_pct','crc_pct_late','breast_pct_late','crc_inc','breast_inc','crc_mort','breast_mort','child_poverty','pct_black_nh']].to_csv('results/p05/p05b_county_dataset.csv',index=False)
open('results/p05/p05b_results.md','w').write(out.getvalue()); print(out.getvalue())
